  errText(e){const c=e&&e.code;if(c==="bad_key")return "The Claude API key was rejected. Check it under Stats → Settings.";if(c==="not_granted")return S.sample?"You have not allowed this app to ask Claude. Allow it when the prompt appears.":"Add your Claude API key under Stats → Settings to use this.";if(c==="rate_limited")return "Claude is busy right now. Try again in a minute.";if(c==="invalid_json")return "Claude's answer could not be read. Try once more.";if(c==="cancelled")return "";if(c==="image_rejected")return "That image could not be used. Try a clearer JPEG or PNG.";return "Claude could not answer ("+(c||"error")+"). Try again.";},
  shape(L){if(L.c2)return `Each element is an object: {"en": a concise plain-English definition (8-15 words), "target": the advanced English word, idiom, collocation or phrasal verb itself, "roman": null, "literal": the literal image behind an idiom or phrasal verb, else null, "note": one or two sentences on origin, register (formal, informal, literary, British, American) and a typical collocation or usage warning, "pos": part of speech, "type": "word" or "phrase", "gender": null, "conj": for phrasal and irregular verbs an array of 2-4 {"label": e.g. past / separable / passive, "target": form, "roman": null}, else null, "example": {"target": one natural sentence using it, "roman": null, "en": a simple paraphrase}}. Reply with ONLY the JSON array, no prose.`;return `Each element is an object: {"en": English meaning (short), "target": the item written in ${L.name}${L.roman?" in its native script":""}, "roman": ${L.roman?L.roman:"null (Latin script, no transliteration needed)"}, "literal": the word-for-word or morpheme-by-morpheme meaning when it differs from the plain English meaning, else null, "note": one or two plain sentences on where the word comes from or why it is written or said this way (etymology, script quirk, loanword history, cultural use), "pos": part of speech, "type": "word" or "phrase", "gender": {"m": {"target": ..., "roman": ...}, "f": {"target": ..., "roman": ...}} only when ${L.name} has distinct masculine and feminine forms of this item, else null, "conj": for verbs an array of 4 to 6 {"label": person or tense, "target": form, "roman": transliteration or null} with the most useful forms, else null, "example": {"target": one short natural sentence using it, "roman": transliteration or null, "en": its English}}. Reply with ONLY the JSON array, no prose.`;},
